    if ability_ready(0) and not slot_is_dash(0) and not slot_is_reset(0) and not slot_is_shield(0) and not slot_is_heal(0):
        cast_at_unit(0, camp)
    if ability_ready(1) and not slot_is_dash(1) and not slot_is_reset(1) and not slot_is_shield(1) and not slot_is_heal(1):
