    return ability_ready(s) and (slot_stun(s) > 0 or (slot_is_damage(s) and not slot_is_dash(s))) and d <= slot_range(s) + slot_radius(s) and (not slot_is_dash(s) or fuel_remaining() > DASH_FUEL)

